const {test,before,after}=require('node:test');
const assert=require('node:assert/strict');
const fs=require('node:fs');
const {chromium}=require('playwright');
let browser;
before(async()=>{browser=await chromium.launch({headless:true,executablePath:process.env.REVIEWER_CHROMIUM_PATH||undefined,args:['--no-sandbox']});});
after(async()=>{await browser?.close();});
const review={title:'A stronger start',summary:'Your idea is clear. Try opening with the surprise.',strength:'The topic gives viewers a clear point of interest.',nextStep:'You could put the reveal first.',categories:[{name:'Hook',observation:'The script opens with a greeting.',suggestion:'Try leading with the surprising fact.'}],hook:'The one thing nobody told you about studying.',outline:['Proposed: open with a question','Show an example','Invite a reply'],caption:'Try this on your next study day.',experiment:'Compare average watch time on your next two posts.',limitations:'Based on supplied evidence only.'};
async function setup({onboarding=false}={}){
 const context=await browser.newContext({viewport:{width:390,height:844},deviceScaleFactor:1});
 const page=await context.newPage();
 await page.addInitScript(({onboarding})=>{if(!onboarding)localStorage.setItem('tiktok-profile-v1',JSON.stringify({setupDone:true,niche:'Study tips'}));},{onboarding});
 await page.route('https://js.puter.com/**',route=>route.fulfill({contentType:'application/javascript',body:`window.__calls=[];window.__signed=true;window.__fail=false;window.__reply=${JSON.stringify(JSON.stringify(review))};window.puter={auth:{isSignedIn:()=>window.__signed,signIn:async()=>{window.__signed=true;}},ai:{chat:async(messages,options)=>{window.__calls.push({messages,options});if(window.__fail)throw new Error('Quota exceeded');return {message:{content:window.__reply}};}}};`}));
 const html=fs.readFileSync('app/src/main/assets/tiktok_reviewer.html','utf8').replace('/* REVIEWER_SCRIPT */',fs.readFileSync('app/src/main/assets/tiktok_reviewer.js','utf8'));
 await page.route('https://reviewer.test/',route=>route.fulfill({contentType:'text/html',body:html}));
 await page.goto('https://reviewer.test/');await page.waitForFunction(()=>window.puter);
 return {page,context};
}
test('onboarding asks one question at a time and is skippable',async()=>{const {page,context}=await setup({onboarding:true});assert.match(await page.locator('#stepQuestion').textContent(),/creator journey/);await page.getByRole('button',{name:'Just getting started'}).click();assert.match(await page.locator('#stepQuestion').textContent(),/love creating/);await page.locator('#skipSetup').click();assert.equal(await page.locator('#home').isVisible(),true);assert.equal(await page.evaluate(()=>JSON.parse(localStorage.getItem('tiktok-profile-v1')).stage),'Just getting started');await context.close();});
test('review requires evidence and consent but no optional questions',async()=>{const {page,context}=await setup();await page.locator('#homeReview').click();await page.locator('#review').click();assert.match(await page.locator('#error').textContent(),/Add a video/);await page.locator('#scriptMode').click();await page.locator('#script').fill('Hello everyone, here is one study tip.');await page.locator('#review').click();assert.match(await page.locator('#error').textContent(),/allow the AI/);await page.locator('#consent').check();await page.locator('#review').click();await page.locator('#results').waitFor({state:'visible'});assert.equal(await page.locator('#resultTitle').textContent(),review.title);assert.equal(await page.locator('#optionalDetails').getAttribute('open'),null);const call=await page.evaluate(()=>window.__calls[0]);assert.equal(call.options.model,'qwen/qwen3.6-27b');assert.match(call.messages[0].content,/Be brief, friendly/);assert.equal(await page.locator('#reportCards details[open]').count(),0);await context.close();});
test('video request includes timestamped stills; script mode excludes hidden video',async()=>{const {page,context}=await setup();await page.locator('#homeReview').click();await page.evaluate(()=>{frames=[{time:1.5,image:'data:image/jpeg;base64,abc'}];});await page.locator('#consent').check();await page.locator('#review').click();await page.locator('#results').waitFor({state:'visible'});let call=await page.evaluate(()=>window.__calls[0]);assert.equal(call.options.model,'gpt-4.1-mini');assert.match(call.messages[1].content[1].text,/1.5/);await page.locator('#newReview').click();await page.locator('#scriptMode').click();await page.locator('#script').fill('Only review this script');await page.locator('#review').click();await page.locator('#results').waitFor({state:'visible'});call=await page.evaluate(()=>window.__calls[1]);assert.equal(call.options.model,'qwen/qwen3.6-27b');assert.equal(typeof call.messages[1].content,'string');await context.close();});
test('failed provider request preserves content and does not create a saved review',async()=>{const {page,context}=await setup();await page.locator('#homeReview').click();await page.evaluate(()=>{window.__fail=true;});await page.locator('#scriptMode').click();await page.locator('#script').fill('Keep my content');await page.locator('#consent').check();await page.locator('#review').click();await page.waitForFunction(()=>document.getElementById('error').textContent.includes('usage limit'));assert.equal(await page.locator('#script').inputValue(),'Keep my content');assert.equal(await page.locator('#review').isEnabled(),true);assert.equal(await page.evaluate(()=>localStorage.getItem('tiktok-reviews-v1')),null);await context.close();});
test('ideas and weekly plans are actionable and can be bookmarked and deleted',async()=>{const {page,context}=await setup();await page.locator('#homeReview').click();await page.locator('[data-nav=ideas]').click();await page.locator('#ideaTopic').fill('Study habits');await page.evaluate(()=>{window.__reply=JSON.stringify({title:'Fresh study ideas',summary:'Three starting points',ideas:[{title:'Try a recall challenge',hook:'Can you remember this?',outline:['Ask','Show','Compare'],caption:'Try it',hashtags:['#Study','#Learn'],why:'Fits study tips'}]});});await page.locator('#generateIdeas').click();await page.locator('#results').waitFor({state:'visible'});assert.equal(await page.locator('.hashtag').count(),2);assert.equal(await page.locator('.numbered-beat').count(),3);await page.locator('#bookmark').click();await page.locator('[data-nav=saved]').click();await page.locator('#favoritesOnly').click();assert.equal(await page.locator('#history .list-card').count(),1);await page.locator('[data-nav=ideas]').click();await page.locator('#generatePlan').click();await page.locator('#results').waitFor({state:'visible'});const task=await page.evaluate(()=>JSON.parse(window.__calls[1].messages[1].content).task);assert.match(task,/seven entries/);await page.locator('[data-nav=saved]').click();await page.locator('#clear').click();assert.equal(await page.evaluate(()=>JSON.parse(localStorage.getItem('tiktok-reviews-v1')).length),0);await context.close();});
test('provider text is rendered safely and mobile layout fits the screen',async()=>{const {page,context}=await setup();await page.locator('#homeReview').click();await page.evaluate(()=>{window.__reply=JSON.stringify({title:'<img src=x onerror="window.hacked=true">',summary:'Good starting point',nextStep:'<script>window.hacked=true</script>'});});await page.locator('#scriptMode').click();await page.locator('#script').fill('Test draft');await page.locator('#consent').check();await page.locator('#review').click();await page.locator('#results').waitFor({state:'visible'});assert.equal(await page.evaluate(()=>window.hacked),undefined);assert.equal(await page.locator('#reportCards script').count(),0);assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true,JSON.stringify(await page.evaluate(()=>Array.from(document.querySelectorAll('body *')).filter(e=>!e.hidden&&e.getBoundingClientRect().right>innerWidth+1).map(e=>({tag:e.tagName,id:e.id,width:e.getBoundingClientRect().width,text:e.textContent.slice(0,100)})))));await context.close();});
